<script setup>defineProps({status:String,error:String,pending:Object,busy:Boolean});defineEmits(['retry','reload']);</script>
<template><div class="save-notice" :class="{'save-pending':pending&&!busy}"><p role="status">{{status}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="pending&&!busy">Your selected {{pending.action==='rate'?'rating':'answer'}}: <strong>{{pending.payload.answer||pending.payload.confidence}}</strong>. Retry when connected. Timed rounds still follow the server deadline.</p><div v-if="pending&&!busy" class="row"><button class="primary" @click="$emit('retry')">Retry saving</button><button @click="$emit('reload')">Discard unsent selection and reload</button></div></div></template>
